const debugSort = await browserjs(tabId, () => {
  const btn = document.querySelector('[data-testid="sort-button"]');
  // Find react fiber
  const key = Object.keys(btn || {}).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
  if (!key) return "No react fiber found";

  let fiber = btn[key];
  const handlers = [];
  while (fiber) {
    if (fiber.memoizedProps) {
      handlers.push({
        name: fiber.type?.name || fiber.type?.displayName || (typeof fiber.type === 'string' ? fiber.type : 'Component'),
        props: Object.keys(fiber.memoizedProps)
      });
    }
    fiber = fiber.return;
  }
  return handlers.slice(0, 15);
});
console.log(JSON.stringify(debugSort, null, 2));

