      if (fiber.memoizedProps.entityData) {
        result.entityDataCount = fiber.memoizedProps.entityData?.length;
        result.firstEntity = fiber.memoizedProps.entityData?.[0];
      }
      if (fiber.memoizedProps.changeSort) {
        result.hasChangeSort = true;
      }
