const tabId = 118779795;
const topAgentsExp = await browserjs(tabId, async () => {
  // Get the agents from the current page
  const articles = Array.from(document.querySelectorAll('article'));
  const links = articles.map(art => {
    const name = art.querySelector('h2')?.textContent?.trim();
    const city = art.querySelectorAll('p')[2]?.textContent?.trim();
    const href = art.querySelector('a[href*="/residential/agent/"]')?.href;
    return { name, city, href };
  }).filter(a => a.href);

  const results = [];
  for (const agent of links.slice(0, 15)) {
    try {
      const res = await fetch(agent.href);
      const html = await res.text();
      const expMatch = html.match(/(\d+)\s+Years?\s+Experience/i);
      results.push({
        name: agent.name,
        city: agent.city,
        experience: expMatch ? expMatch[0] : "Not found",
        years: expMatch ? parseInt(expMatch[1], 10) : 0,
        url: agent.href
      });
    } catch (e) {
      results.push({ name: agent.name, error: e.message });
    }
  }
  return results;
});
console.log(JSON.stringify(topAgentsExp, null, 2));

